const github = 'https://github.com/satakshijoshi2006-ship-it/';
const projects = [
 {title:'Java web app deployment',label:'DEVOPS / JAVA',repo:'java-project-maven-new',description:'A Java and Maven project with a deployed streaming-interface preview, captured in the supplied screenshot.',tags:['Java','Maven','Deployment'],image:'assets/maven-preview.png',visual:'Java + Maven',category:'BUILD & DEPLOY',bg:'#17233c',fg:'#a9c8ff'},
 {title:'Grilli',label:'WEB DEVELOPMENT',repo:'grilli',description:'A restaurant website project. Explore the live experience and its source repository.',tags:['Website','Live demo'],live:'https://satakshijoshi2006-ship-it.github.io/grilli/',visual:'Grilli.',category:'RESTAURANT WEBSITE',bg:'#202b26',fg:'#e0d8b0',bottom:'A TABLE FOR YOUR NEXT EXPERIENCE'},
 {title:'Nestack submission',label:'WEB APPLICATION',repo:'Shatakshi_Nestack_Submission',description:'My Nestack submission, with a live deployment available on Vercel.',tags:['Web application','Vercel'],live:'https://shatakshi-nestack-submission.vercel.app/',visual:'Nestack',category:'APPLICATION SUBMISSION',bg:'#e6eafa',fg:'#394681',bottom:'FROM SOURCE TO LIVE APPLICATION'},
 {title:'Travel Quest',label:'PROJECT / EXPLORATION',repo:'Travel_Quest',description:'Travel Destination Explorer, presented as part of the NGIT MERN skilling project presentations.',tags:['Travel','Project presentation'],live:'https://satakshijoshi2006-ship-it.github.io/Travel_Quest/',visual:'Travel\nQuest.',category:'TRAVEL DESTINATION EXPLORER',bg:'#dceced',fg:'#235c62',bottom:'DISCOVER YOUR NEXT DESTINATION'},
 {title:'Neurovision',label:'WEB PROJECT',repo:'NEUROVISION-FINAL',description:'Explore the Neurovision project through its live preview and GitHub source.',tags:['Website','Live demo'],live:'https://satakshijoshi2006-ship-it.github.io/NEUROVISION-FINAL/',visual:'Neurovision',category:'PROJECT SHOWCASE',bg:'#25243c',fg:'#b8aefa',bottom:'EXPLORE THE LIVE EXPERIENCE'},
 {title:'Dockerized expense tracker',label:'CONTAINERIZATION / DEVOPS',repo:'expense-tracker',description:'Containerized an open-source Flask expense tracker using Docker, with SQLite and local deployment verification.',tags:['Docker','Flask','SQLite'],document:'assets/docker-report.pdf',visual:'Expenses,\ncontained.',category:'DOCKER DEPLOYMENT',bg:'#dfebfb',fg:'#2e5391',bottom:'PYTHON 3.11 / DOCKER / SQLITE'}
];
const grid = document.querySelector('#project-grid');
projects.forEach((p,i)=>{
 const article=document.createElement('article');article.className='project-card';
 const button=document.createElement('button');button.className='project-open';button.setAttribute('aria-haspopup','dialog');button.setAttribute('aria-label',`Explore ${p.title}: repository and preview`);
 button.innerHTML=`<div class="project-info"><h3>${p.title}</h3><span class="text-link">View project</span></div>`;
 button.addEventListener('click',()=>openProject(p));article.append(button);grid.append(article);
});
const dialog=document.querySelector('#project-dialog');
function openProject(p){
 document.querySelector('#dialog-content').innerHTML=`<h2 class="dialog-title" id="dialog-title">${p.title}</h2><p class="dialog-description">${p.description}</p><div class="project-options"><div class="option"><h3>01 / GitHub repository</h3><p>Explore the source code and project files.</p><a class="button primary" href="${github+p.repo}" target="_blank" rel="noopener">View GitHub repository</a></div><div class="option"><h3>02 / Preview & resources</h3><p>${p.live?'Open the deployed application in a new tab.':p.image?'See the supplied deployment screenshot below.':'Explore the Docker deployment report below. This application was run locally.'}</p><div class="option-links">${p.live?`<a class="button secondary" href="${p.live}" target="_blank" rel="noopener">Open live preview</a>`:''}${p.image?`<a class="button secondary" href="${p.image}" target="_blank" rel="noopener">Open screenshot</a>`:''}${p.document?`<a class="button secondary" href="${p.document}" target="_blank" rel="noopener">Read project report</a>`:''}</div>${p.live?'<p class="empty-preview">No additional screenshots or project documents supplied.</p>':''}</div></div>${p.image?`<div class="project-media"><h3>Deployment snapshot</h3><img src="${p.image}" alt="Supplied Java Maven deployment screenshot"><p class="media-caption">Captured preview of the deployed application. A public live-preview URL was not supplied.</p></div>`:''}${p.document?`<div class="project-document"><span>Docker expense tracker · Project report</span><a href="${p.document}" target="_blank" rel="noopener">Open PDF document</a></div><p class="media-caption">Adapted from the open-source expense tracker by hakiKhuva. My contribution focuses on Docker containerization and deployment.</p>`:''}`;
 dialog.showModal();document.body.classList.add('modal-open');
}
document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());
dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));
dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))dialog.close()});

